nginx_config:
daemon off;
master_process on;
worker_processes 2;
pid /tmp/aegisx-bench-9k40ng57/nginx.pid;
error_log /tmp/aegisx-bench-9k40ng57/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-9k40ng57/body;
    proxy_temp_path /tmp/aegisx-bench-9k40ng57/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 10.42.1.170:3800; keepalive 256; }
    server {
        listen 10.42.1.79:59713   reuseport;
        location / {
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host 10.42.1.170:3800;
            proxy_request_buffering off;
            proxy_buffering off;
            proxy_pass http://origin;
        }
    }
}

caddy_config:
{
    admin off
    auto_https off
}
:10967 {
    bind 10.42.1.79
    reverse_proxy 10.42.1.170:3800
}
